import com.hospital.billing.dto.AppointmentDto;
import com.hospital.billing.dto.InvoiceRequestDto;
import com.hospital.billing.dto.InvoiceResponseDto;
import com.hospital.billing.dto.PatientDto;
import com.hospital.billing.model.Invoice;
import com.hospital.billing.repository.InvoiceRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class InvoiceServiceTest {

    @Mock
    private InvoiceRepository invoiceRepository;

    @Mock
    private PatientServiceClient patientServiceClient;

    @Mock
    private AppointmentServiceClient appointmentServiceClient;

    @InjectMocks
    private InvoiceService invoiceService;

    // GreyTest trace: createInvoice | invoice creation after duplicate and client lookups succeed | BR-018 -> TP-081 -> TC-160
    @Test
    void createInvoice_GeneratesFormattedInvoiceNumber() {
        // Arrange
        InvoiceRequestDto request = new InvoiceRequestDto();
        request.setPatientId(201L);
        request.setAppointmentId(301L);
        request.setConsultationFee(new BigDecimal("100.0"));
        request.setMedicationCharges(new BigDecimal("0.0"));
        request.setTestCharges(new BigDecimal("0.0"));
        request.setOtherCharges(new BigDecimal("0.0"));
        request.setDiscount(new BigDecimal("0.0"));
        request.setTax(new BigDecimal("0.0"));
        request.setNotes("Khám định kỳ");

        PatientDto patient = new PatientDto(201L, "An", "Nguyen", "an@example.com", "0123456789");
        AppointmentDto appointment = new AppointmentDto(301L, 201L, "An Nguyen", 401L, "Bac si A", "Noi khoa", "2025-04-10", "09:00", "SCHEDULED", new BigDecimal("100.00"));
        LocalDateTime persistedAt = LocalDateTime.of(2025, 4, 10, 9, 0);

        when(invoiceRepository.existsByAppointmentId(301L)).thenReturn(false);
        when(patientServiceClient.getPatientById(201L)).thenReturn(patient);
        when(appointmentServiceClient.getAppointmentById(301L)).thenReturn(appointment);
        when(invoiceRepository.save(any(Invoice.class))).thenAnswer(invocation -> {
            Invoice saved = invocation.getArgument(0);
            saved.setId(1001L);
            saved.setCreatedAt(persistedAt);
            saved.setUpdatedAt(persistedAt);
            return saved;
        });

        // Act
        InvoiceResponseDto result = invoiceService.createInvoice(request);

        // Assert
        ArgumentCaptor<Invoice> savedCaptor = ArgumentCaptor.forClass(Invoice.class);
        verify(invoiceRepository).save(savedCaptor.capture());
        Invoice saved = savedCaptor.getValue();
        assertTrue(Pattern.matches("INV-[0-9]{14}", result.getInvoiceNumber()));
        assertEquals(saved.getInvoiceNumber(), result.getInvoiceNumber());
        assertEquals(1001L, result.getId());
        assertEquals(201L, result.getPatientId());
        assertEquals("An Nguyen", result.getPatientName());
        assertEquals(301L, result.getAppointmentId());
        assertEquals("2025-04-10", result.getAppointmentDate());
        assertEquals(request.getConsultationFee(), result.getConsultationFee());
        assertEquals(request.getMedicationCharges(), result.getMedicationCharges());
        assertEquals(request.getTestCharges(), result.getTestCharges());
        assertEquals(request.getOtherCharges(), result.getOtherCharges());
        assertEquals(request.getDiscount(), result.getDiscount());
        assertEquals(request.getTax(), result.getTax());
        assertEquals("100.0", result.getTotalAmount().toPlainString());
        assertEquals("0.0", result.getPaidAmount().toPlainString());
        assertEquals("100.0", result.getBalanceAmount().toPlainString());
        assertEquals(Invoice.InvoiceStatus.PENDING, result.getStatus());
        assertEquals("Khám định kỳ", result.getNotes());
        assertEquals(persistedAt, result.getCreatedAt());
        assertEquals(persistedAt, result.getUpdatedAt());
        assertNotNull(result);
        verify(invoiceRepository).existsByAppointmentId(eq(301L));
        verify(patientServiceClient).getPatientById(eq(201L));
        verify(appointmentServiceClient).getAppointmentById(eq(301L));
    }
}
